(function(){"use strict";window.BIomieFlightPlan=window.BIomieFlightPlan||{};function l(t){const i=document.getElementById("flightAlerts");if(!i)return;const n=window.BIomieFlightPlan.Dom;if(n){if(!t||!t.length){i.style.display="none";return}i.style.display="flex",i.innerHTML=t.slice(0,5).map(e=>{const o=e.level==="danger"?"error":e.level==="warning"?"warning":"info",r=e.action&&e.action.url?`<a class="biomie-btn biomie-btn--secondary biomie-btn--sm" href="${n.escH(e.action.url)}">${n.escH(e.action.label||"Abrir")}</a>`:"";return`<div class="fp-alert-item ${e.level}">
        <span class="material-symbols-rounded fp-alert-icon">${o}</span>
        <div class="fp-alert-content">
          <h4>${n.escH(e.title||"Alerta")}</h4>
          <p>${n.escH(e.message||"")}</p>
        </div>
        ${r}
      </div>`}).join("")}}window.BIomieFlightPlan.Alerts={renderAlerts:l}})();
